import org.springframework.stereotype.Component;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * 幂等支撑：指纹覆盖 requestId、操作类型与全部业务字段；
 * 同键同参返回首次响应快照，同键异参返回 409 且不产生副作用。
 */
@Component
public class Idempotency {

    private final IdempotentRepo repo;
    private final ObjectMapper objectMapper;

    public Idempotency(IdempotentRepo repo, ObjectMapper objectMapper) {
        this.repo = repo;
        this.objectMapper = objectMapper;
    }

    /** 幂等执行结果：status 为 HTTP 状态码，body 为响应体（重放时为 JsonNode 快照）。 */
    public record Result(int status, Object body, boolean replay) {
    }

    /**
     * 计算业务指纹。入参按固定顺序拼接入签，集合需由调用方排好序。
     */
    public String fingerprint(Operation operation, String requestId, Object... fields) {
        StringBuilder sb = new StringBuilder(operation.name()).append('|').append(requestId);
        for (Object f : fields) {
            sb.append('|');
            if (f != null) {
                sb.append(f);
            }
        }
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] digest = md.digest(sb.toString().getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /**
     * 按 requestId 执行幂等逻辑：已存在则校验指纹并重放，否则执行业务并固化首次结果。
     * 业务异常同样按首次结果固化，保证同键同参一致返回。
     */
    public Result execute(Operation operation, String requestId, String fingerprint,
                          java.util.function.Supplier<Outcome> action) {
        IdempotentRow existing = repo.find(requestId);
        if (existing != null) {
            if (!existing.operation().equals(operation.name())
                    || !existing.fingerprint().equals(fingerprint)) {
                throw ApiException.conflict("requestId 已用于不同业务参数的请求");
            }
            JsonNode snapshot;
            try {
                snapshot = objectMapper.readTree(existing.resultJson());
            } catch (Exception e) {
                throw new IllegalStateException("幂等快照解析失败", e);
            }
            return new Result(existing.httpStatus(), snapshot, true);
        }

        Outcome outcome;
        try {
            outcome = action.get();
        } catch (ApiException e) {
            persist(requestId, operation, fingerprint, e.getStatus().value(),
                    new com.example.starter.survey.api.Dtos.ErrorResponse(e.getError(), e.getMessage()));
            throw e;
        }
        persist(requestId, operation, fingerprint, outcome.status(), outcome.body());
        return new Result(outcome.status(), outcome.body(), false);
    }

    private void persist(String requestId, Operation operation, String fingerprint,
                         int status, Object body) {
        String json;
        try {
            json = objectMapper.writeValueAsString(body);
        } catch (Exception e) {
            throw new IllegalStateException("幂等快照序列化失败", e);
        }
        repo.insert(requestId, operation.name(), fingerprint, status, json);
    }

    /** 业务动作产出：HTTP 状态码 + 响应体。 */
    public record Outcome(int status, Object body) {
        public static Outcome ok(Object body) {
            return new Outcome(HttpStatus.OK.value(), body);
        }
    }
}

