    // ---------- 同键重放 / 异参冲突 / 签发终态 ----------

    @Test
    void sameRequestIdSameParamsReplaysFirstResult() {
        Idempotency.Result first = service.applySurvey(
                new Dtos.ApplySurveyRequest("r-replay", SHIP1, "ANNUAL"));
