    // ---------- 证书原子交接 ----------

    @Test
    void newCertificateAtomicallyReplacesOldOne() {
        Long firstSurvey = apply(SHIP1, "ANNUAL", "r-apply-c1");
        board(firstSurvey, LocalDate.of(2026, 6, 15), List.of(), "r-board-c1");
